/*
 * model_infer.h - bounded decision-tree inference engine + rule baseline.
 *
 * The tree itself (arrays) is generated by tools/ml/train.py into
 * src/model/model_tree.h; the baseline thresholds into src/model/baseline_params.h.
 */
#ifndef SIG_MODEL_INFER_H
#define SIG_MODEL_INFER_H

#include "sig_types.h"
#include "features.h"

typedef struct {
    uint8_t  cls;          /* sig_class_t */
    uint8_t  confidence;   /* leaf purity in percent (training distribution) */
    uint16_t leaf;         /* node index of the reached leaf */
    uint8_t  depth;        /* comparisons performed */
} sig_prediction_t;

/* Run the exported tree. Returns false (and cls = UNKNOWN) on a corrupt model
 * or a non-finite feature, so invalid inputs never become a valid prediction. */
bool sig_model_predict(const float *features, sig_prediction_t *out);

/* Rule-based baseline (thresholds tuned on the training sessions only). */
uint8_t sig_baseline_predict(const float *features);

/* Model identity, for logs and the LCD. */
const char *sig_model_version(void);
bool sig_model_is_placeholder(void);
int sig_model_node_count(void);
int sig_model_max_depth(void);
uint32_t sig_model_size_bytes(void);

#endif /* SIG_MODEL_INFER_H */
